import os
import torch


class Config:
    """
    Configuration class for the Bird Species Classification task.
    Centralizes all hyperparameters, file paths, and model settings.
    """

    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_3"
    SUBMISSION_DIR = "./submission"

    # Data Sources
    SPECTROGRAM_DIR = os.path.join(INPUT_DIR, "supplemental_data", "spectrograms")

    # Metadata Paths (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Paths
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # Data Parameters
    # ==========================================
    NUM_CLASSES = 19

    # Image Dimensions
    ORIG_HEIGHT = 256  # Height of source spectrograms
    IMG_HEIGHT = 224  # Input height for ResNet
    IMG_WIDTH = 512  # Input width for ResNet
    CROP_WIDTH = 512  # Width of temporal crops (approx 4 seconds)
    STRIDE = 256  # Stride for sliding window inference

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    MODEL_NAME = "resnet50"
    PRETRAINED = True
    DROPOUT = 0.2

    # ==========================================
    # Training Settings
    # ==========================================
    N_FOLDS = 5  # Stratified K-Fold
    EPOCHS = 50  # Max epochs (controlled by early stopping)
    BATCH_SIZE = 32  # A100 has 40GB, can handle larger, but dataset is small
    LEARNING_RATE = 1e-4  # Start low for fine-tuning
    WEIGHT_DECAY = 1e-4  # Regularization

    # Optimization
    PATIENCE = 10  # Early stopping patience
    SCHEDULER_T_MAX = 10  # Cosine Annealing cycles

    # Augmentation
    MIXUP_ALPHA = 0.2  # Beta distribution parameter for Mixup
    SPECAUG_TIME_MASK = 40
    SPECAUG_FREQ_MASK = 20

    # ==========================================
    # Compute & Debugging
    # ==========================================
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debugging flags to limit dataset size for rapid testing
    DEBUG = False
    DEBUG_SAMPLES = 50  # Number of samples to use if DEBUG is True

    @classmethod
    def initialize(cls):
        """
        Creates necessary working and submission directories.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        print(f"Directories initialized: {cls.WORKING_DIR}, {cls.SUBMISSION_DIR}")
        print(f"Device: {cls.DEVICE}")
